fun activeEmails(users: List<User>): List<String> =
    users.filter { it.isActive && it.email != null }
        .map { it.email!! }
        .sortedBy { it.lowercase() }

export function Price({ sku }) {
  const [price, setPrice] = useState(null);
  useEffect(() => {
    fetch(`/api/price/${sku}`).then(r => r.json()).then(d => setPrice(d.amount));
  }, []);
  return <span>{price ?? '...'}</span>;
}
